d h2:not(:first-child){margin-top:25px}.settings-card label{display:block;color:#476172;font-size:14px;font-weight:650;margin:8px 0}.settings-card input,.settings-card select{width:100%;padding:10px;margin-top:5px;border:1px solid #cbd9e0;border-radius:7px;background:white;color:#173447}.settings-card input[type=color]{width:65px;height:42px;padding:4px}.settings-card .primary{margin-top:11px}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:8px 16px}.type-row{display:flex;align-items:center;gap:10px;padding:8px;border-bottom:1px solid #e6edf0}.type-row strong{flex:1;font-size:14px}.type-row input[type=color]{width:48px}.secret-state{font-size:13px;color:#607987}.settings-card form{border-top:1px solid #e7edf0;margin-top:17px;padding-top:14px}[hidden]{display:none!important}@media(max-width:850px){.settings-grid{grid-template-columns:1fr}.formgrid{grid-template-columns:1fr}}.day.weekend{background:#f1f5f7}.day.holiday{background:#fff1e2}.holiday-name{font-size:12px;color:#9a591e;font-weight:700;margin:1px 0 6px;white-space:normal}.holiday-legend{padding:8px 17px;font-size:12px;color:#607987}.holiday-legend a{color:#276b8c}.weekdays div:nth-child(n+6){background:#e8eff2}</style></head><body><header><div class="brand"><span class="mark">▦</span> График <b>изпълнение</b></div><div class="headright"><a href="/" style="color:#fff">Настъпили промени</a> · График изпълнение</div></header><main class="shell"><nav class="app-tabs" aria-label="Раздели"><button id="tabCalendar" class="selected" type="button">Календар</button><a href="/admin.php">⚙ Администрация</a><a href="/">INFO</a></nav><div id="calendarView"><div class="top"><div><h1>График за изпълнение</h1><p>Планиране по месец · проверка на техника · назначаване на екип</p></div><button class="primary" id="new">+ Нова заявка</button></div><div class="summary"><div class="metric"><span>Чакащи за изпълнение</span><strong id="waitingCount">0</strong></div><div class="metric"><span>Чакат техника</span><strong id="missingCount">0</strong></div><div class="metric"><span>Готови за насрочване</span><strong id="readyCount">0</strong></div><div class="metric"><span>Задачи тази седмица</span><strong id="weekCount">0</strong></div></div><section class="monthstats" aria-label="Статистика за месеца"><div><strong>Статистика за <span id="statsMonth"></span></strong><small>По дати в избрания месец</small></div><div class="stat"><b id="plannedCount">0</b><span>Общо планирани</span></div><div class="stat done"><b id="doneCount">0</b><span>Завършени</span></div><div class="stat"><b id="remainingCount">0</b><span>Оставащи</span></div><div class="stat"><b id="donePercent">0%</b><span>Изпълнение</span></div></section><div class="sourcebar"><strong>Настъпили промени</strong><div id="sourceCounts">Зареждане…</div><a href="/">Отвори справката</a></div><div class="layout"><aside class="side"><div><h2>Вид работа</h2><div id="filters"></div></div><div class="section"><h2>Чакащи заявки</h2><div id="queue"></div></div></aside><section class="calendar"><div class="calhead"><div class="nav"><button id="prev" aria-label="Предишен месец">‹</button><button id="next" aria-label="Следващ месец">›</button><button class="today" id="todayBtn">Днес</button></div><h2 id="month"></h2><select id="calendarYear" aria-label="Година"></select></div><div class="weekdays"><div>Понеделник</div><div>Вторник</div><div>Сряда</div><div>Четвъртък</div><div>Петък</div></div><div class="holiday-legend">Сиво: почивен ден · Оранжево: официален празник или неприсъствен ден · <a href="https://kik-info.com/spravochnik/calendar/" target="_blank" rel="noopener">Източник: КиК Инфо</a><span id="calendarStatus"></span></div><div class="grid" id="grid"></div></section></div></div><section id="settingsView" class="settings-view" hidden><h1>Настройки на изпълнението</h1><p class="hint">Видове работа и канали за известия</p><div class="settings-grid"><div class="settings-card"><h2>Видове работа</h2><div id="typesSettings"></div><form id="addTypeForm"><label>Нов вид работа<input id="newTypeName" placeholder="Напр. Профилактика" required maxlength="70"></label><label>Цвят<input id="newTypeColor" type="color" value="#247a9a"></label><button class="primary">Добави</button></form></div><div class="settings-card"><h2>Съхранение на оферти · ownCloud</h2><form id="owncloudForm"><div class="formgrid"><label>ownCloud URL<input id="owncloud_url" placeholder="https://cloud.example.com"></label><label>Потребител<input id="owncloud_user" autocomplete="off"></label><label>Парола<input id="owncloud_password" type="password" autocomplete="new-password" placeholder="Въведи за промяна"></label><label>Основна папка<input id="owncloud_root" value="INFO" placeholder="INFO"></label></div><p class="secret-state" id="owncloudSecretState"></p><div style="display:flex;gap:8px"><button class="primary">Запази</button><button type="button" id="testOwncloud">Тествай връзката</button></div><p id="owncloudState" class="hint"></p></form><h2>Имейл · SMTP</h2><form id="channelsForm"><div class="formgrid"><label>SMTP сървър<input id="smtp_host" autocomplete="off" placeholder="smtp.example.com"></label><label>Порт<input id="smtp_port" type="number" min="1" max="65535" value="587"></label><label>Защита<select id="smtp_security"><option value="tls">STARTTLS</option><option value="ssl">SSL/TLS</option><option value="none">Без</option></select></label><label>Потребител<input id="smtp_user" autocomplete="off"></label><label>Парола<input id="smtp_password" type="password" autocomplete="new-password" placeholder="Въведи за промяна"></label><label>Имейл на подателя<input id="smtp_from" type="email" placeholder="tehnik@tim.bg"></label><label>Име на подателя<input id="smtp_from_name"></label><label>Получател на напомнянията<input id="notification_email" type="email" placeholder="tehnik@tim.bg"></label></div><p class="secret-state" id="smtpSecretState"></p><h2>Telegram</h2><div class="formgrid"><label>Токен на бота<input id="telegram_token" type="password" autocomplete="new-password" placeholder="Въведи за промяна"></label><label>Chat ID за известия<input id="telegram_chat_id" placeholder="Личен чат или група"></label></div><p class="secret-state" id="telegramSecretState"></p><button class="primary">Запази настройките</button><p id="deliveryState" class="hint"></p><p id="settingsMessage" role="status"></p></form><h2>Последни известия</h2><div id="notificationLog" class="hint">Няма изпратени известия.</div></div></div><p class="hint">Напомнянията се изпращат автоматично след попълване на валидни SMTP или Telegram данни.</p></section></main><div class="backdrop" id="panelBackdrop"></div><aside class="detailpanel" id="detailPanel" aria-label="Детайли на заявка"></aside><div class="modalback" id="back"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="dialogTitle"><h2 id="dialogTitle"></h2><div id="dialogBody"></div><div class="actions" id="dialogActions"></div></div></div><script>
let types=[['Нови обекти','#2d9c72','#e4f6ed'],['Добавка на техника','#8260af','#f0eafa'],['Заявка','#d8913c','#fff1df'],['Окабеляване','#3985bc','#e5f2fb'],['Преместване на техника','#8d9a39','#f1f4dc'],['Демонтаж','#81919b','#eef1f3']];
const now=new Date(), initialMonth=new Date(now.getFullYear(),now.getMonth(),1);let view=new Date(initialMonth), active=new Set(types.map(x=>x[0]));
let changes=[];let jobs=[];let sourceObjects=[];
const yearCalendars=new Map();
async function loadCalendarYear(y){if(yearCalendars.has(y))return;try{let r=await fetch('calendar-api.php?year='+y,{cache:'no-store'});if(!r.ok)throw new Error('Липсва календар');let data=await r.json();yearCalendars.set(y,data);render()}catch(e){document.getElementById('calendarStatus').textContent=' · Няма данни за '+y+' г.'}}
function holidayFor(d){let data=yearCalendars.get(d.getFullYear()),item=data?.days?.[dayKey(d)];return item||{off:d.getDay()===0||d.getDay()===6,name:''}}
function showMonth(y,m){view=new Date(y,m,1);render();loadCalendarYear(view.getFullYear());if(m===0)loadCalendarYear(y-1);if(m===11)loadCalendarYear(y+1)}
function at(day){return new Date(initialMonth.getFullYear(),initialMonth.getMonth(),day).toLocaleDateString('en-CA')}function displayDate(v){if(!v)return '';let m=String(v).match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?m[3]+'-'+m[2]+'-'+m[1]:v}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function typeOf(t){return types.find(x=>x[0]===t)||types[2]}function ready(j){return j.checked.every(Boolean)}function fmt(d){return d.toLocaleDateString('bg-BG',{month:'long',year:'numeric'})}function dayKey(d){return d.toLocaleDateString('en-CA')}function modal(title,body,buttons){document.getElementById('dialogTitle').textContent=title;document.getElementById('dialogBody').innerHTML=body;document.getElementById('dialogActions').innerHTML=buttons;document.getElementById('back').classList.add('show')};function close(){document.getElementById('back').classList.remove('show')}document.getElementById('back').addEventListener('click',e=>{if(e.target.id==='back')close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
function render(){jobs.forEach(j=>{if(j.type&&!types.some(t=>t[0]===j.type)){types.push([j.type,'#607d8b','#eef3f5']);active.add(j.type)}});document.getElementById('month').textContent=fmt(view);let years=document.getElementById('calendarYear');years.innerHTML=Array.from({length:7},(_,i)=>view.getFullYear()-3+i).map(y=>`<option value="${y}" ${y===view.getFullYear()?'selected':''}>${y}</option>`).join('');let calendar=yearCalendars.get(view.getFullYear());document.getElementById('calendarStatus').textContent=calendar?' · Проверен: '+new Date(calendar.checked_at).toLocaleDateString('bg-BG')+' · Промени при последната проверка: '+(calendar.last_changes?.length||0):'';document.getElementById('filters').innerHTML=types.map(t=>`<label class="filter"><input type="checkbox" data-type="${esc(t[0])}" ${active.has(t[0])?'checked':''}><span class="swatch" style="background:${t[1]}"></span>${esc(t[0])}</label>`).join('');document.querySelectorAll('[data-type]').forEach(x=>x.onchange=()=>{x.checked?active.add(x.dataset.type):active.delete(x.dataset.type);render()});let q=jobs.filter(j=>!j.date);document.getElementById('waitingCount').textContent=q.length;document.getElementById('missingCount').textContent=q.filter(j=>!ready(j)).length;document.getElementById('readyCount').textContent=q.filter(ready).length;let monday=new Date(now);monday.setDate(now.getDate()-(now.getDay()+6)%7);let friday=new Date(monday);friday.setDate(monday.getDate()+4);document.getElementById('weekCount').textContent=jobs.filter(j=>j.date&&j.date>=dayKey(monday)&&j.date<=dayKey(friday)).length;let monthJobs=jobs.filter(j=>j.date&&j.date.slice(0,7)===dayKey(view).slice(0,7)),done=monthJobs.filter(j=>j.completed).length;document.getElementById('statsMonth').textContent=fmt(view);document.getElementById('plannedCount').textContent=monthJobs.length;document.getElementById('doneCount').textContent=done;document.getElementById('remainingCount').textContent=monthJobs.length-done;document.getElementById('donePercent').textContent=(monthJobs.length?Math.round(done/monthJobs.length*100):0)+'%';let monthChanges=changes.filter(x=>x.month===dayKey(view).slice(0,7));let cc=document.getElementById('changesCount'),cl=document.getElementById('changesList');if(cc)cc.textContent=monthChanges.length;if(cl)cl.innerHTML=monthChanges.length?monthChanges.slice().reverse().map(x=>`<div class="changeitem"><time>${esc(x.when)}</time>${esc(x.text)}</div>`).join(''):'<p class="nochanges">Няма отбелязани промени през този месец.</p>';document.getElementById('queue').innerHTML=q.length?q.map(j=>`<div class="queue"><strong>№ ${esc(j.no)} · ${esc(j.name)}</strong><small>${esc(j.type)}</small><span class="pill ${ready(j)?'p-green':'p-red'}">${ready(j)?'Техниката е налична':'Чака техника'}</span><br><button data-open="${j.id}">Отвори заявката</button></div>`).join(''):'<p class="hint">Няма чакащи заявки.</p>';let first=new Date(view.getFullYear(),view.getMonth(),1),offset=(first.getDay()+6)%7,start=new Date(view.getFullYear(),view.getMonth(),1-offset),cells=[];for(let week=0;week<6;week++){for(let wd=0;wd<5;wd++){let d=new Date(start);d.setDate(start.getDate()+week*7+wd);let key=dayKey(d),holiday=holidayFor(d),items=jobs.filter(j=>j.date===key&&active.has(j.type));cells.push(`<div class="day ${d.getMonth()===view.getMonth()?'':'muted'} ${key===dayKey(now)?'today':''} ${holiday.name?'holiday':holiday.off?'weekend':''}"><div class="date">${d.getDate()}</div>${holiday.name?`<div class="holiday-name">${esc(holiday.name)}</div>`:''}${items.map(j=>{let t=typeOf(j.type);return `<button class="event ${j.completed?'doneevent':''}" data-open="${j.id}" style="border-color:${t[1]};background:${t[2]}" title="${esc(j.name)}">${j.completed?'<span class="donebadge">Готов</span>':''}<b>${esc(j.time)}</b> №${esc(j.no)} ${esc(j.name)}</button>`}).join('')}</div>`)}if(new Date(start.getFullYear(),start.getMonth(),start.getDate()+week*7+4).getMonth()!==view.getMonth()&&week>=3)break}document.getElementById('grid').innerHTML=cells.join('');document.querySelectorAll('[data-open]').forEach(x=>x.onclick=()=>openJob(Number(x.dataset.open)))}
function closePanel(){document.getElementById('detailPanel').classList.remove('open');document.getElementById('panelBackdrop').classList.remove('open')}document.getElementById('panelBackdrop').onclick=closePanel;
function openJob(id){let j=jobs.find(x=>x.id===id),t=typeOf(j.type),panel=document.getElementById('detailPanel');panel.innerHTML=`<div class="panelhead"><div><small>${esc(j.type)}</small><h2>Заявка №${esc(j.no)}</h2></div><button id="closePanel" aria-label="Затвори панела">×</button></div><div class="panelbody"><h3 style="margin-top:0">${esc(j.name)}</h3><div class="detail"><span>Дата и час</span><strong>${j.date?esc(displayDate(j.date)+' · '+j.time):'Не е насрочен'}</strong></div><div class="detail"><span>Екип</span><strong>${esc(j.team||'Не е назначен')}</strong></div><div class="panelstatus"><div style="margin-bottom:8px"><span class="pill ${j.completed?'p-green':j.date?'p-amber':'p-red'}">${j.completed?'Завършен':j.date?'Планиран':'Чакащ'}</span></div><span class="pill ${ready(j)?'p-green':'p-red'}">${ready(j)?'Техниката е налична':'Има липсваща техника'}</span></div><div class="panel-section"><h3>Данни за обекта</h3><div class="detail"><span>№ на обект</span><strong>${esc(j.object_number||'—')}</strong></div><div class="detail"><span>Клиент</span><strong>${esc(j.client||j.name||'—')}</strong></div><div class="detail"><span>Адрес</span><strong>${esc(j.address||'—')}</strong></div><div class="detail"><span>Телефон</span><strong>${esc(j.phone||'—')}</strong></div></div><div class="panel-section"><h3>Проблем и констатация</h3><div class="detail"><span>Проблем</span><strong>${esc(j.problem||'—')}</strong></div><div class="detail"><span>Описание</span><strong>${esc(j.description||'—')}</strong></div><div class="detail"><span>Техническа констатация</span><strong>${esc(j.technical_opinion||'—')}</strong></div><div class="detail"><span>Необходими материали / техника</span><strong>${esc(j.required_materials||'—')}</strong></div></div><div class="panel-section"><h3>Проверка на техника</h3>${j.equipment.length?j.equipment.map((item,i)=>`<label class="checkrow"><input type="checkbox" data-equipment="${i}" ${j.checked[i]?'checked':''}> ${esc(item)}</label>`).join(''):'<p class="hint">Няма посочена техника.</p>'}</div>${j.request_type!=='Ремонт/Обслужване'?`<div class="panel-section"><h3>Данни от „Настъпили промени“</h3><div id="sourceForJob">${sourceFor(j.no)}</div></div>`:''}<div class="panel-section"><h3>Напомняния</h3><div class="reminder">Ден преди монтажа · Telegram и имейл до екипа<br>При липсваща техника · известие до отговорника</div><p class="hint">Известията се изпращат към получателя и чата, посочени в „Настройки“.</p></div></div><div class="panelbottom">${j.date?`<button class="finish ${j.completed?'undo':''}" id="finish">${j.completed?'Върни в планирани':'✓ Завърши'}</button>`:''}<button class="primary" id="schedule">${j.date?'Промени графика':'Насрочи монтаж'}</button></div>`;panel.classList.add('open');document.getElementById('panelBackdrop').classList.add('open');document.getElementById('closePanel').onclick=closePanel;let finish=document.getElementById('finish');if(finish)finish.onclick=()=>{j.completed=!j.completed;changes.push({month:j.date.slice(0,7),when:new Date().toLocaleString('bg-BG'),text:`№${j.no} · ${j.completed?'Завършен монтаж':'Върнат в планирани'}`});persist();render();openJob(id)};panel.querySelectorAll('[data-equipment]').forEach(x=>x.onchange=()=>{j.checked[Number(x.dataset.equipment)]=x.checked;persist();render();openJob(id)});document.getElementById('schedule').onclick=()=>{closePanel();schedule(id)}}
function schedule(id){let j=jobs.find(x=>x.id===id);modal(`Планиране · №${esc(j.no)}`,`${!ready(j)?'<p class="pill p-red">Внимание: част от техниката липсва</p>':''}<label>Дата<input type="date" id="date" value="${esc(j.date||dayKey(now))}"></label><label>Час<input type="time" id="time" value="${esc(j.time||'09:00')}"></label><label>Екип<select id="team"><option value="">Избери екип</option>${['Екип 1','Екип 2','Екип 3'].map(x=>`<option ${j.team===x?'selected':''}>${x}</option>`).join('')}</select></label><p class="hint">Монтажът ще се появи в месечния календар.</p>`,`<button id="cancel">Назад</button><button class="primary" id="save">Запази в графика</button>`);document.getElementById('cancel').onclick=()=>{close();openJob(id)};document.getElementById('save').onclick=()=>{let date=document.getElementById('date').value,time=document.getElementById('time').value,team=document.getElementById('team').value;if(!date||!time||!team){alert('Попълни дата, час и екип.');return}let conflict=jobs.find(x=>x.id!==id&&x.date===date&&x.time===time&&x.team===team);if(conflict&&!confirm(`Екипът вече има монтаж по заявка №${conflict.no} в този час. Да запазя ли?`))return;let previous=j.date?`${displayDate(j.date)} ${j.time} · ${j.team}`:'Без дата';j.date=date;j.time=time;j.team=team;changes.push({month:date.slice(0,7),when:new Date().toLocaleString('bg-BG'),text:`№${j.no} · ${previous==='Без дата'?'Насрочен':'Променен график'}: ${previous} → ${displayDate(date)} ${time} · ${team}`});persist();view=new Date(Number(date.slice(0,4)),Number(date.slice(5,7))-1,1);close();render()}}
document.getElementById('new').onclick=()=>{window.location.assign('/zayavki.php')};document.getElementById('prev').onclick=()=>showMonth(view.getFullYear(),view.getMonth()-1);document.getElementById('next').onclick=()=>showMonth(view.getFullYear(),view.getMonth()+1);document.getElementById('todayBtn').onclick=()=>showMonth(now.getFullYear(),now.getMonth());document.getElementById('calendarYear').onchange=e=>showMonth(Number(e.target.value),view.getMonth());async function loadAll(){try{let [a,b,c]=await Promise.all([fetch('montaji-api.php',{cache:'no-store'}),fetch('api.php',{cache:'no-store'}),fetch('settings-api.php',{cache:'no-store'})]);if(a.ok){let v=await a.json();jobs=Array.isArray(v.jobs)?v.jobs:[];changes=Array.isArray(v.changes)?v.changes:[]}if(b.ok){let v=await b.json();sourceObjects=Array.isArray(v)?v:[]}if(c.ok){let v=await c.json();applySettings(v)}}catch(e){console.error('Грешка при зареждане',e);alert('Не успях да заредя данните от сървъра.')}render();renderSource()}async function persist(){try{let r=await fetch('montaji-api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jobs,changes})});if(!r.ok){let error=await r.json();throw new Error(error.error||'HTTP '+r.status)}await loadAll()}catch(e){console.error(e);alert(e.message);await loadAll()}}function sourceFor(no){let linked=jobs.find(j=>String(j.no)===String(no));let objectNo=linked?.object_number||no;let rows=sourceObjects.filter(x=>String(x.number||'').trim()===String(objectNo).trim());return rows.length?rows.map(x=>`<div class="detail"><span>${esc(x.date||'')}</span><strong>${esc(({active:'Нов',disconnected:'Изключен',moved:'Преместен'})[x.status]||x.status)} · ${esc(x.address||'')}</strong></div>`).join(''):'<p class="hint">Няма запис за този номер в справката.</p>'}function renderSource(){let m=dayKey(view).slice(0,7),monthRows=sourceObjects.filter(x=>String(x.date||'').startsWith(m));document.getElementById('sourceCounts').innerHTML=`<span>За избрания месец: <b>${monthRows.length}</b></span><span>Нови: <b>${monthRows.filter(x=>x.status==='active').length}</b></span><span>Изключени: <b>${monthRows.filter(x=>x.status==='disconnected').length}</b></span><span>Преместени: <b>${monthRows.filter(x=>x.status==='moved').length}</b></span>`}const oldRender=render;render=function(){oldRender();renderSource()};
let savedSettings={};let typeRecords=[];
function tint(hex){let n=parseInt(hex.slice(1),16),r=(n>>16)&255,g=(n>>8)&255,b=n&255;return `rgb(${Math.round(r*.14+255*.86)},${Math.round(g*.14+255*.86)},${Math.round(b*.14+255*.86)})`}
function applySettings(data){typeRecords=Array.isArray(data.types)?data.types:[];if(typeRecords.length){types=typeRecords.map(x=>[x.name,x.color,tint(x.color)]);active=new Set(types.map(x=>x[0]))}savedSettings=data.settings||{};let logs=Array.isArray(data.notification_log)?data.notification_log:[];document.getElementById('notificationLog').innerHTML=logs.length?logs.map(x=>`<div class="changeitem">№${esc(x.job_id)} · ${esc(x.kind)} · ${esc(x.channel)} · ${esc(x.status)}${x.error?' · '+esc(x.error):''}</div>`).join(''):'Няма изпратени известия.';for(let key of ['owncloud_url','owncloud_user','owncloud_root','smtp_host','smtp_port','smtp_security','smtp_user','smtp_from','smtp_from_name','notification_email','telegram_chat_id']){let el=document.getElementById(key);if(el)el.value=savedSettings[key]??''}document.getElementById('owncloud_password').value='';document.getElementById('owncloudSecretState').textContent=savedSettings.owncloud_password_configured?'ownCloud паролата е запазена. Остави празно, за да я запазиш.':'Няма запазена ownCloud парола.';document.getElementById('smtp_password').value='';document.getElementById('telegram_token').value='';document.getElementById('smtpSecretState').textContent=savedSettings.smtp_password_configured?'SMTP паролата е запазена. Остави празно, за да я запазиш.':'Няма запазена SMTP парола.';document.getElementById('deliveryState').textContent=`Имейл: ${savedSettings.smtp_host&&savedSettings.smtp_from&&savedSettings.notification_email?'конфигуриран':'непълен'} · Telegram: ${savedSettings.telegram_token_configured&&savedSettings.telegram_chat_id?'конфигуриран':'непълен'}`;document.getElementById('telegramSecretState').textContent=savedSettings.telegram_token_configured?'Telegram токенът е запазен. Остави празно, за да го запазиш.':'Няма запазен Telegram токен.';document.getElementById('typesSettings').innerHTML=typeRecords.map(x=>`<div class="type-row"><span class="swatch" style="background:${esc(x.color)}"></span><strong>${esc(x.name)}</strong><input type="color" data-color-id="${x.id}" value="${esc(x.color)}" aria-label="Цвят за ${esc(x.name)}"></div>`).join('');document.querySelectorAll('[data-color-id]').forEach(el=>el.onchange=async()=>{try{let d=await settingsPost({action:'color',id:Number(el.dataset.colorId),color:el.value});applySettings(d);render();showSettingsMessage('Цветът е запазен.')}catch(e){showSettingsMessage(e.message,true)}})}
function showSettingsMessage(message,error=false){let el=document.getElementById('settingsMessage');el.textContent=message;el.style.color=error?'#b33e30':'#25764e'}
async function settingsPost(payload){let r=await fetch('settings-api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await r.json();if(!r.ok)throw new Error(data.error||'Грешка при запазване');return data}
document.getElementById('tabCalendar').onclick=()=>switchTab('calendar');function switchTab(tab){document.getElementById('calendarView').hidden=tab!=='calendar';document.getElementById('settingsView').hidden=tab!=='settings';document.getElementById('tabCalendar').classList.toggle('selected',tab==='calendar');(document.getElementById('tabSettings')||{classList:{toggle:()=>{}}}).classList.toggle('selected',tab==='settings')}
document.getElementById('addTypeForm').onsubmit=async e=>{e.preventDefault();try{let d=await settingsPost({action:'add_type',name:document.getElementById('newTypeName').value.trim(),color:document.getElementById('newTypeColor').value});applySettings(d);document.getElementById('newTypeName').value='';render();showSettingsMessage('Видът работа е добавен.')}catch(err){showSettingsMessage(err.message,true)}};
document.getElementById('owncloudForm').onsubmit=async e=>{e.preventDefault();let settings={};for(let key of ['owncloud_url','owncloud_user','owncloud_password','owncloud_root'])settings[key]=document.getElementById(key).value;try{let d=await settingsPost({action:'owncloud',settings});applySettings(d);document.getElementById('owncloudState').textContent='Настройките са запазени.'}catch(err){document.getElementById('owncloudState').textContent=err.message}};
document.getElementById('testOwncloud').onclick=async()=>{let el=document.getElementById('owncloudState');el.textContent='Проверка…';try{let r=await fetch('settings-api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'test_owncloud'})}),d=await r.json();if(!r.ok)throw new Error(d.error||'Грешка');el.textContent='✓ '+d.message}catch(e){el.textContent='✗ '+e.message}};
document.getElementById('channelsForm').onsubmit=async e=>{e.preventDefault();let settings={};for(let key of ['smtp_host','smtp_port','smtp_security','smtp_user','smtp_password','smtp_from','smtp_from_name','telegram_token','telegram_chat_id'])settings[key]=document.getElementById(key).value;try{let d=await settingsPost({action:'channels',settings});applySettings(d);showSettingsMessage('Настройките са запазени.')}catch(err){showSettingsMessage(err.message,true)}};
loadAll();loadCalendarYear(view.getFullYear());if(view.getMonth()===0)loadCalendarYear(view.getFullYear()-1);if(view.getMonth()===11)loadCalendarYear(view.getFullYear()+1);
</script></body></html>
